let ctx,docFilter='全部',agreementTab='templates',agreementQuery='',agreementCategory='全部',agreementStatus='全部';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const s=()=>migrate(ctx.state()),r=()=>ctx.role();
const button=(label,action,id='',allowed=[])=>`<button class="secondary compact" data-op="${action}" data-id="${esc(id)}" ${allowed.length&&!allowed.includes(r())?'disabled':''}>${label}</button>`;
