const row=(...cells)=>`<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
const names=id=>s().materials.find(m=>m.holder===id)?.holderName||s().movements.find(m=>m.holder===id)?.person||recipients(s()).find(x=>x.id===id)?.name||s().founders.find(f=>f.id===id)?.name||'—';
const labels={onboardAccountSubmit:'提交账号权限申请',onboardAccountReview:'审核账号权限',onboardAccountActivate:'确认账号开通',onboardProfileSubmit:'提交创业者档案',onboardProfileReview:'审核创业者档案',onboardStockApply:'申请行政物资',onboardStockReview:'审核并预留物资',onboardStockDeliver:'确认领取出库',onboardStockReturn:'归还行政物资',founderProfile:'维护创业者档案',founderTestPlan:'设置测试目标',founderFormalSubmit:'提交正式评估',founderFormalReview:'审核正式评估',founderAssetApply:'申请办公资产',founderAssetReview:'审核资产派发',founderAssetDeliver:'确认派发',founderAssetReturn:'归还资产',purchaseReview:'财务审核采购',purchaseReceive:'登记采购到货',purchaseConfirm:'上级确认入库',issue:'物资派发',return:'资产归还',replace:'资产换发',damage:'标记损坏',saleReview:'财务审核销售',saleExecute:'登记销售结果',saleClose:'财务入账结案',founderNeed:'建立招募需求',founderCandidate:'登记候选人',founderAdvance:'招募步骤办理',employeeFounder:'员工登记事业主理人',founderSetup:'提交人事手续',founderSetupReview:'审核人事手续',ventureSubmit:'提交项目申请',ventureReview:'总经理审核项目',ventureMonth:'更新月度评估',fundingSubmit:'申请阶段预算',fundingReview:'总经理审批阶段预算'};
const hist=x=>`<h3>办理记录</h3>${(x.history||[]).map(h=>`<div class="version"><b>${esc(labels[h.action]||h.action||h.stage)} · ${esc(h.role)}</b><small>${esc(new Date(h.time).toLocaleString('zh-CN'))}</small><p>${esc(h.note)}</p></div>`).join('')||'<p>暂无办理记录</p>'}`;
const files=xs=>(xs||[]).map(f=>button('下载 '+esc(f.name),'download',f.id)).join(' ');
function db(){return new Promise((resolve,reject)=>{const q=indexedDB.open('chuangjie-hr-files',1);q.onupgradeneeded=()=>q.result.createObjectStore('files',{keyPath:'id'});q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(Error('文件存储不可用'));});}
async function storeFiles(list){const result=[];for(const f of list){if(!f.size)continue;if(f.size>10*1024*1024)throw Error('单个文件不得超过10MB');const id=crypto.randomUUID(),d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put({id,blob:f});tx.oncomplete=resolve;tx.onerror=()=>reject(Error('文件保存失败'));});d.close();result.push({id,name:f.name,size:f.size,type:f.type});}return result;}
async function download(id){const all=[...s().documents.flatMap(d=>d.versions.flatMap(v=>v.files||[])),...s().docRequests.flatMap(x=>x.files||[]),...s().purchases.flatMap(x=>x.files||[]),...s().sales.flatMap(x=>x.files||[]),...s().founderCandidates.flatMap(x=>x.planFiles||[]),...s().founders.flatMap(x=>[...(x.setupFiles||[]),...(x.formalReview?.files||[]),...(x.profile?.files||[]),...(x.profileHistory||[]).flatMap(p=>p.files||[])]),...s().founderAssets.flatMap(x=>[...(x.files||[]),...(x.returnFiles||[])]),...s().ventures.flatMap(x=>x.months.flatMap(m=>m.files||[]))];const meta=all.find(f=>f.id===id);if(!meta)throw Error('附件不存在');const d=await db(),record=await new Promise((resolve,reject)=>{const q=d.transaction('files').objectStore('files').get(id);q.onsuccess=()=>resolve(q.result);q.onerror=reject;});d.close();if(!record)throw Error('本浏览器没有该附件，请使用原上传浏览器');const a=document.createElement('a');a.href=URL.createObjectURL(record.blob);a.download=meta.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function form(label,action,id,body,extra=''){if(!id&&/Submit$|founderCandidate$|founderNeed$|onboardStockApply$/.test(action))body+=field('totalDue','流程总截止日期','date',addDays(businessDay(),14),'min="'+businessDay()+'"')+'<p class="sub">请按本事项确认总期限；普通审批默认2个自然日，各节点不超过总期限。</p>';if(action==='docSubmit'&&!body.includes('founder-steps'))body=flowStrip([['上传或更新文件','人事专员'],['管理层审核','管理层'],['发布生效','系统']],0)+body;if(action==='purchaseSubmit')body='<p class="form-intro">填写物资规格和采购预算，提交后由财务审核。</p>'+body+'<div class="purchase-estimate">预计采购总额 <strong id="purchase-total">待填写数量与单价</strong><small>有价资产逐件编码；易耗品按数量管理。</small></div>';ctx.panel(label,`${formFlowContext(action,id)}${operationContext(action,id)}<form data-op-form="${action}" data-id="${esc(id||'')}" ${extra}><div class="form-grid">${body}</div><p class="form-error" role="alert"></p><div class="form-footer"><button type="submit" class="primary">${({docSubmit:'提交管理层审批',purchaseSubmit:'提交财务审核',purchaseReview:'提交审核结果',purchaseReceive:'提交到货记录',purchaseConfirm:'确认处理结果',saleSubmit:'提交财务审核',founderNeed:'发布用人需求',founderCandidate:'保存候选人',founderAdvance:'提交本步骤结果'})[action]||'确认提交'}</button></div></form>`,true);}
export function documentsPage(scope=''){if(scope==='agreements')return agreementsPage();const docs=s().documents.filter(d=>!d.subject&&d.kind!=='template'),requests=s().docRequests.filter(r=>!r.subject&&r.kind!=='template'),matched=docs.filter(d=>!documentQuery||[d.title,d.category].join(' ').includes(documentQuery));return title('制度与档案','统一维护有效文件，新增与更新审批后发布。',button('＋ 上传 / 新建文件','docNew','',['人事专员','创业发展总监']))+metrics([['生效文件',docs.length,'保留历史版本'],['待审批',requests.filter(x=>x.status==='待审批').length,'管理层审核后发布'],['待签收',s().receipts.filter(x=>!x.signedAt).length,'按版本跟踪签收'],['已驳回',requests.filter(x=>x.status==='已驳回').length,'补充后重新提交']])+`<section class="work-library"><div class="agreement-tabs">${[['library','有效文件',docs.length],['reviews','新增与更新审批',requests.length],['receipts','签收记录',s().receipts.length]].map(([key,t,n])=>`<button data-op="documentTab" data-id="${key}" aria-selected="${documentTab===key}">${t} <span>${n}</span></button>`).join('')}</div>${documentTab==='library'?`<div class="work-toolbar"><label>查找文件<input id="document-query" placeholder="文件名称或分类" value="${esc(documentQuery)}"></label>${button('查询','documentSearch')}${button('重置','documentReset')}</div><div class="agreement-grid">${matched.map(d=>`<article class="agreement-card"><div class="agreement-card-top"><span class="agreement-file-icon">▤</span>${chip('已生效')}</div><small>${esc(d.category||'制度文件')}</small><h3>${esc(d.title)}</h3><div class="agreement-meta"><span>当前版本<b>V${d.versions.length}</b></span><span>生效日期<b>${esc(d.versions.at(-1)?.date||'—')}</b></span></div><div class="agreement-card-actions">${button('查看版本与文件','docVersion',d.id)}${button('申请更新','docEdit',d.id,['人事专员','创业发展总监'])}</div></article>`).join('')||emptyBlock('暂无匹配文件','可调整搜索或上传新文件。')}</div>`:documentTab==='reviews'?`<div class="doc-filters work-inner">${['全部','待审批','已驳回','已通过'].map(k=>`<button data-op="docFilter" data-id="${k}" class="${docFilter===k?'primary':'secondary'}">${k} ${requests.filter(x=>k==='全部'||x.status===k).length}</button>`).join('')}</div>`+table(['文件名称','分类','申请日期','状态','操作'],requests.filter(x=>docFilter==='全部'||x.status===docFilter).map(x=>row('<b>'+esc(x.title)+'</b>',esc(x.category),x.created,chip(x.status),button('查看申请 / 审批','docRequest',x.id)))):table(['员工','文件名称','版本','签收状态','操作'],s().receipts.filter(x=>docs.some(d=>d.id===x.docId)).map(x=>row(esc(names(x.employeeId)),esc(docs.find(d=>d.id===x.docId)?.title),'V'+x.version,chip(x.signedAt?'已签收':'待签收'),`<button class="secondary compact" data-action="process" data-id="${x.processId}">查看签收流程</button>`)))}</section>`;}
const money=v=>'¥'+Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:2});
const chip=(v)=>`<span class="agreement-pill ${/驳回|损坏|超期/.test(v)?'red':/待|审核|确认|采购入库|预留/.test(v)?'amber':''}">${esc(v)}</span>`;
